// Contract for `eventsSidebar` in sidebars.js, the sidebar ADR 0012 derives
// from scripts/lib/events-catalog.mjs rather than autogenerating. The two
// tests that read sidebars.js for structure, tests/site-config.test.mjs and
// tests/docs-contract.test.mjs, look only at `{type: 'autogenerated'}`
// entries, so a hand-built sidebar is outside both: a year category in the
// wrong order, an event doc missing from its year, or a doc id that resolves
// to no page would all reach `docusaurus build` (or production) unnoticed.
//
// The shape assertions run against eventsSidebarItems() with fixtures so each
// arm (year order, per-year order, expanded newest year) is exercised
// regardless of how many events docs/events/ holds; the live assertions tie
// the exported sidebar to the live catalog and to the pages on disk.

import assert from 'node:assert/strict';
import { existsSync } from 'node:fs';
import { join } from 'node:path';
import test from 'node:test';
import { fileURLToPath } from 'node:url';

import {
  collectEvents,
  eventsSidebarItems,
  groupByYear,
} from '../scripts/lib/events-catalog.mjs';

const repoRoot = fileURLToPath(new URL('..', import.meta.url));
const docsRoot = join(repoRoot, 'docs');

const { default: sidebars } = await import('../sidebars.js');

const FIXTURE_YEARS = [
  {
    year: 2026,
    events: [
      { docId: 'events/2026/kubecon-na' },
      { docId: 'events/2026/kubecon-eu' },
    ],
  },
  { year: 2025, events: [{ docId: 'events/2025/kubecon-na' }] },
];

test('the sidebar opens with the section index, then one category per year', () => {
  const items = eventsSidebarItems(FIXTURE_YEARS);
  assert.equal(items[0], 'events/index');
  assert.deepEqual(
    items.slice(1).map((item) => item.type),
    ['category', 'category'],
  );
});

test('year categories are labelled by year and list their events in catalog order', () => {
  const [, newest, older] = eventsSidebarItems(FIXTURE_YEARS);
  assert.equal(newest.label, '2026');
  assert.deepEqual(newest.items, [
    'events/2026/kubecon-na',
    'events/2026/kubecon-eu',
  ]);
  assert.equal(older.label, '2025');
  assert.deepEqual(older.items, ['events/2025/kubecon-na']);
});

test('only the newest year starts expanded; every year is collapsible', () => {
  const [, newest, older] = eventsSidebarItems(FIXTURE_YEARS);
  assert.equal(newest.collapsed, false);
  assert.equal(older.collapsed, true);
  assert.equal(newest.collapsible, true);
  assert.equal(older.collapsible, true);
});

test('with no event pages the sidebar is just the index', () => {
  assert.deepEqual(eventsSidebarItems([]), ['events/index']);
});

test('the exported eventsSidebar is built from the live catalog', () => {
  const expected = eventsSidebarItems(groupByYear(collectEvents(docsRoot)));
  assert.deepEqual(sidebars.eventsSidebar, expected);
  assert.ok(
    sidebars.eventsSidebar.length > 1,
    'docs/events/ holds no event pages, so the sidebar has nothing to list',
  );
});

test('every doc id in eventsSidebar resolves to a page on disk', () => {
  const ids = sidebars.eventsSidebar.flatMap((item) =>
    typeof item === 'string' ? [item] : item.items,
  );
  const missing = ids.filter(
    (id) =>
      !['.md', '.mdx'].some((ext) => existsSync(join(docsRoot, `${id}${ext}`))),
  );
  assert.deepEqual(missing, [], 'eventsSidebar names doc ids with no page');
});
